```python
class Vector:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def ___(self, otro):
        return Vector(self.x + otro.x, self.y + otro.y)

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

print(Vector(1, 2) + Vector(3, 4))
